update public.sections set data = '{"eyebrow":"SEO for local, regional, and industrial businesses","heading":"Search Visibility, Explained Every Month.","body":"Jordan Marketing Consultants does one thing: search visibility for local, regional, and industrial businesses. Every month you get a plain recap of what was done, why, and what changed.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"},"collage":[{"kind":"report","label":"Every month","title":"Monthly Recap","items":["What was done","Why it matters","What changed"]},{"kind":"growth","label":"Over time","title":"Visibility Built","items":["Search","Maps","Local grid"]},{"kind":"coverage","label":"Where you appear","title":"Local Surfaces","items":["Map results","Local search","Profile panel"]},{"kind":"roadmap","label":"The plan","title":"SEO Roadmap","items":["Priorities set","Content queued","Fixes tracked"]},{"kind":"serp","label":"What a result looks like","title":"Found, Then Chosen","items":["Jordan Marketing Consultants","jordanmarketingconsultants.com","Map pack","Local search","Profile panel"]}]}'::jsonb, type = 'heroCentered', tone = null where key = 'hero' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"eyebrow":"SEO Growth Paths","heading":"Two Paths, Sorted by Where You Compete","body":"Different businesses need different SEO strategies. Which one fits comes down to reach: a defined area, or several markets at once.","columns":2,"cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses that need stronger visibility in Google Search, Google Maps, and local service-area searches.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"trending-up","body":"For regional, national, and industry-focused companies competing across larger search markets.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, type = 'cardGrid', tone = 'surface' where key = 'growth-paths' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"treatment":"statement","heading":"No Mystery SEO. No Confusing Reports. No Guessing What You Paid For.","body":"Most agencies keep the work behind a login and the reasoning to themselves. JMC does the opposite. You see what was done, why it was done, and what it changed, in language that does not need translating. That is how the work is run, not a reporting add-on.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, type = 'fullWidthText', tone = null where key = 'transparency' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"eyebrow":"SEO Services","heading":"SEO Work Built Around Strategy, Visibility, and Accountability","body":"Strategy and the monthly recap are the same whichever lane you are in. Underneath them the work splits, because competing in one area and competing across several are not the same problem.","columns":3,"groupLabels":[{"at":0,"label":"Local SEO"},{"at":3,"label":"Traditional SEO"}],"cards":[{"title":"Google Business Profile","icon":"star","body":"Categories, services, posts and review activity. For a lot of local searches the profile is what is being ranked, not the site."},{"title":"Citations & Listings","icon":"shield-check","body":"One standard for your name, address and phone number, applied across the listings that currently disagree with each other."},{"title":"Local Grid Tracking","icon":"map-pin","body":"Visibility measured across a spread of points in the service area rather than as one blended rank, because local results change street by street."},{"title":"Strategic SEO Pages","icon":"file-text","body":"Pages built for specific searches worth competing for, produced to a schedule rather than when there is time."},{"title":"Technical SEO Monitoring","icon":"wrench","body":"Crawling, indexing and site health watched month to month, so a redirect chain or a stray noindex is found before it costs a quarter."},{"title":"Authority Recommendations","icon":"network","body":"What would genuinely strengthen the site''s standing and why, including the parts you are best placed to do yourself. Advice, not bought placements."}],"cta":{"label":"Explore Local SEO","href":"/local-seo-services"}}'::jsonb, type = 'cardGrid', tone = 'white' where key = 'services' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"eyebrow":"Industries","heading":"Where This Method Gets Pointed","body":"One method, aimed at two different kinds of search problem.","groups":[{"label":"Consumer & Community","cards":[{"title":"Home Services & Trades","icon":"wrench","body":"Roofers, plumbers, electricians, and the trades that live on calls from a service area.","href":"/industries/home-services-trades"},{"title":"Healthcare & Wellness","icon":"heart-pulse","body":"Practices and clinics where people check credibility before they ever call.","href":"/industries/healthcare-wellness"},{"title":"Hospitality & Attractions","icon":"utensils","body":"Venues, parks, and places people search for by what they want to do, not by name.","href":"/industries/hospitality-attractions"},{"title":"Professional Services","icon":"briefcase","body":"Firms whose next client is comparing three local options in a single sitting.","href":"/industries/professional-services"}]},{"label":"Industrial & B2B","cards":[{"title":"Energy & Petrochemical","icon":"factory","body":"Operators and suppliers selling technical capability to a small, specific buyer pool.","href":"/industries/energy-petrochemical"},{"title":"Maritime & Logistics","icon":"network","body":"Port, freight, and supply chain businesses working across regions rather than a radius.","href":"/industries/maritime-logistics"},{"title":"Commercial Construction","icon":"hard-hat","body":"Contractors and infrastructure firms bidding well outside one city.","href":"/industries/commercial-construction-infrastructure"},{"title":"Aerospace & Aviation","icon":"compass","body":"Suppliers and services in a market where the search volume is low and the intent is high.","href":"/industries/aerospace-aviation"}]}],"escapeHatch":"The method does not change with the industry. If yours is not listed, it probably still applies.","cta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, type = 'industryGrid', tone = 'surface' where key = 'industries' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"eyebrow":"Clear Reporting","heading":"What You Get Every Month","body":"SEO should not feel vague. Every month you get the same four answers, in the same order, in language that does not need a glossary.","did":"A plain summary of the SEO work completed: content, technical checks, local visibility tasks, and everything else inside the scope.","why":"The reasoning behind each piece of work, and how it supports visibility, relevance, or trust.","changed":"What moved, what did not, and what is still being watched.","next":"The priorities for the coming month, in order, so you always know where the campaign is heading.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, type = 'reportingBlock', tone = 'white' where key = 'monthly-recap' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"eyebrow":"SEO Packages","heading":"SEO Options Built for Different Growth Stages","body":"JMC offers structured SEO options for businesses that need ongoing monthly support or a focused starting point before moving into a longer campaign.","columns":3,"cards":[{"title":"Launch Sprints","icon":"compass","meta":"From $799 one-time","body":"For businesses that need a fixed-scope SEO foundation before deciding on monthly service.","cta":{"label":"View Launch Sprints","href":"/launch-sprints"}},{"title":"Monthly Local SEO","icon":"map-pin","meta":"From $875/mo","body":"For businesses that need consistent local visibility support across search, maps, content, reviews, and reporting.","cta":{"label":"View Local SEO Packages","href":"/monthly-seo-packages#local"}},{"title":"Monthly Traditional SEO","icon":"trending-up","meta":"From $2,295/mo","body":"For businesses targeting regional, national, or competitive industry visibility with a larger search footprint.","cta":{"label":"View Traditional SEO Packages","href":"/monthly-seo-packages#traditional"}}]}'::jsonb, type = 'cardGrid', tone = 'white' where key = 'packages' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"eyebrow":"How It Works","heading":"A Clear SEO Process From Review to Recap","body":"SEO works better when the process is organized. JMC keeps the work focused around visibility, priorities, implementation, and clear communication.","steps":[{"title":"Visibility Review","body":"JMC reviews where your business currently shows up, where visibility is weak, and which opportunities are worth prioritizing."},{"title":"SEO Roadmap","body":"The work is organized around keyword priorities, content needs, local visibility, technical issues, and business goals."},{"title":"Implementation","body":"JMC completes the scoped SEO work, content updates, local optimization, and technical improvements tied to the plan."},{"title":"Monthly Recap","body":"You receive a clear summary of what was completed, what changed, and what should happen next."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, type = 'processSteps', tone = 'surface' where key = 'process' and page_id = (select id from public.pages where slug = '/');
update public.sections set data = '{"heading":"Not Sure Where Your SEO Is Stuck? Start with a Visibility Review.","body":"A review identifies visibility gaps, priority opportunities, and the best next step for your business, market, and goals.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, type = 'finalCta', tone = null where key = 'final-cta' and page_id = (select id from public.pages where slug = '/');
